  }
  expect(mainText).not.toMatch(
    /\b(?:competition|season|fixture|competitor|participant|statistic|event)\s+(?:id|reference)\b/i,
  );
  expect(mainText).not.toMatch(/\bcompetitor\b|\bparticipant\b|\bcursor\b/i);
