import { useCallback, useEffect, useState } from 'react';

type PublicDataState<Data> =
  | { status: 'loading'; data: null; error: null }
  | { status: 'ready'; data: Data; error: null }
  | { status: 'error'; data: null; error: Error };

export function usePublicData<Data>(
  load: (signal: AbortSignal) => Promise<Data>,
  requestKey: string,
) {
  const [reloadCount, setReloadCount] = useState(0);
  const [state, setState] = useState<PublicDataState<Data>>({
    status: 'loading',
    data: null,
    error: null,
  });

  useEffect(() => {
    const controller = new AbortController();
    setState({ status: 'loading', data: null, error: null });

    void load(controller.signal)
      .then((data) => {
        if (!controller.signal.aborted) {
          setState({ status: 'ready', data, error: null });
        }
      })
      .catch((error: unknown) => {
        if (!controller.signal.aborted) {
          setState({
            status: 'error',
            data: null,
            error: error instanceof Error ? error : new Error('The public API request failed.'),
          });
        }
      });

    return () => controller.abort();
  }, [load, reloadCount, requestKey]);

  const reload = useCallback(() => setReloadCount((count) => count + 1), []);

  return { ...state, reload };
}

import type { ReactNode } from 'react';
import { Link } from 'react-router-dom';

interface DetailLayoutProps {
  backLabel: string;
  backTo: string;
  children: ReactNode;
  eyebrow: string;
  title: string;
}

export function DetailLayout({ backLabel, backTo, children, eyebrow, title }: DetailLayoutProps) {
  return (
    <article className="detail-page content-boundary">
      <Link className="back-link" to={backTo}>
        Back to {backLabel}
      </Link>
      <header className="page-heading page-heading--detail">
        <p className="eyebrow">{eyebrow}</p>
        <h1>{title}</h1>
      </header>
      {children}
    </article>
  );
}

export function DetailLoading({ label }: { label: string }) {
  return (
    <div className="state-message state-message--detail" role="status">
      <h1>Loading {label}</h1>
      <p>The published record is being requested from the Sport Analytics API.</p>
    </div>
  );
}

export function DetailError({
  error,
  label,
  reload,
}: {
  error: Error;
  label: string;
  reload(): void;
}) {
  return (
    <div className="state-message state-message--detail state-message--error" role="alert">
      <h1>{label} could not be loaded</h1>
      <p>{error.message}</p>
      <button className="button button--secondary" onClick={reload} type="button">
        Try again
      </button>
    </div>
  );
}

export function RecordFacts({ children }: { children: ReactNode }) {
  return <dl className="record-facts">{children}</dl>;
}

export function RecordFact({ label, value }: { label: string; value: ReactNode }) {
  return (
    <div>
      <dt>{label}</dt>
      <dd>{value}</dd>
    </div>
  );
}

export function RelatedLinks({ children }: { children: ReactNode }) {
  return (
    <nav aria-labelledby="related-records-heading" className="related-records">
      <h2 id="related-records-heading">Related records</h2>
      <div>{children}</div>
    </nav>
  );
}

import { competitionCollectionResponseSchema } from '@sport-analytics/contracts';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { ApiResponseError } from './client';
import { ApiContractError, requestPublicApi } from './public-read';

function response(status: number, body: unknown): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: vi.fn().mockResolvedValue(body),
  } as unknown as Response;
}

describe('public read API client', () => {
  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it('requests and validates public data without an authorization header', async () => {
    const fetchMock = vi.fn().mockResolvedValue(
      response(200, {
        data: [{ competitionId: 'competition-1', name: 'Premier League' }],
        pagination: { nextCursor: null },
      }),
    );
    vi.stubGlobal('fetch', fetchMock);

    const result = await requestPublicApi(
      '/competitions?name=Premier',
      competitionCollectionResponseSchema,
    );

    expect(result.data[0]?.name).toBe('Premier League');
    expect(fetchMock).toHaveBeenCalledWith(
      'http://localhost:3000/api/v1/competitions?name=Premier',
      expect.objectContaining({
        headers: { Accept: 'application/json' },
      }),
    );
    const request = fetchMock.mock.calls[0]?.[1] as RequestInit;
    expect(new Headers(request.headers).has('Authorization')).toBe(false);
  });

  it('exposes a safe backend error message and status', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockResolvedValue(
        response(400, {
          error: { code: 'INVALID_QUERY', message: 'The fixture filters are invalid.' },
        }),
      ),
    );

    const request = requestPublicApi('/fixtures?limit=0', competitionCollectionResponseSchema);

    await expect(request).rejects.toBeInstanceOf(ApiResponseError);
    await expect(request).rejects.toMatchObject({
      message: 'The fixture filters are invalid.',
      status: 400,
    });
  });

  it('rejects a successful response that violates the shared contract', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockResolvedValue(response(200, { data: [{ privateAccountEmail: 'private@test' }] })),
    );

    await expect(
      requestPublicApi('/competitions', competitionCollectionResponseSchema),
    ).rejects.toBeInstanceOf(ApiContractError);
  });
});

