  );

  return (
    <DetailState
      label="Competition"
      load={load}
      render={({ data: competition }) => {
        return (
          <DetailLayout
            backLabel="competitions"
            backTo="/competitions"
            eyebrow="Competition"
            title={competition.name}
          >
            <RelatedCollection
