      scheme: body.getAttribute('data-md-color-scheme'),
      headingFont: heading ? getComputedStyle(heading).fontFamily : null,
      bodyFont: getComputedStyle(body).fontFamily,
      logoSrc: logo?.getAttribute('src') ?? null,
      overflow: document.documentElement.scrollWidth > document.documentElement.clientWidth,
      headerButtonSizes: buttons.map((button) => ({ width: button.getBoundingClientRect().width, height: button.getBoundingClientRect().height })),
